import{_ as d,o as e,c as a,a0 as i}from"./chunks/framework.jwovEGr5.js";const b=JSON.parse('{"title":"리눅스 시스템의 이해","description":"","frontmatter":{},"headers":[],"relativePath":"outta-space/project/리눅스-실무의-이해-리눅스-시스템의-이해.md","filePath":"outta-space/project/리눅스-실무의-이해-리눅스-시스템의-이해.md"}'),r={name:"outta-space/project/리눅스-실무의-이해-리눅스-시스템의-이해.md"};function o(l,t,s,c,h,n){return e(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="리눅스-시스템의-이해" tabindex="-1">리눅스 시스템의 이해 <a class="header-anchor" href="#리눅스-시스템의-이해" aria-label="Permalink to &quot;리눅스 시스템의 이해&quot;">​</a></h1><h2 id="리눅스와-하드웨어" tabindex="-1">리눅스와 하드웨어 <a class="header-anchor" href="#리눅스와-하드웨어" aria-label="Permalink to &quot;리눅스와 하드웨어&quot;">​</a></h2><h3 id="컴퓨터의-구성-요소" tabindex="-1">컴퓨터의 구성 요소 <a class="header-anchor" href="#컴퓨터의-구성-요소" aria-label="Permalink to &quot;컴퓨터의 구성 요소&quot;">​</a></h3><table tabindex="0"><thead><tr><th>구성 요소</th><th>역할</th><th>예시</th></tr></thead><tbody><tr><td>CPU</td><td>명령 해석·연산과 시스템 제어</td><td>ALU, 제어장치, 레지스터</td></tr><tr><td>주기억장치</td><td>실행 중인 명령과 데이터 저장</td><td>RAM, ROM</td></tr><tr><td>입력장치</td><td>외부 데이터를 컴퓨터에 전달</td><td>키보드, 마우스, OCR, OMR</td></tr><tr><td>출력장치</td><td>처리 결과를 사용자에게 전달</td><td>모니터, 프린터, HMD</td></tr><tr><td>보조기억장치</td><td>대용량 데이터를 비휘발성으로 저장</td><td>HDD, SSD, 광학 디스크</td></tr></tbody></table><h4 id="cpu" tabindex="-1">CPU <a class="header-anchor" href="#cpu" aria-label="Permalink to &quot;CPU&quot;">​</a></h4><ul><li>레지스터: CPU 내부의 가장 빠르고 작은 임시 저장장치</li><li>ALU(Arithmetic Logic Unit): 산술·논리·비교 연산</li><li>제어장치(Control Unit): 명령을 해석하고 각 장치의 동작을 제어</li></ul><h4 id="주기억장치" tabindex="-1">주기억장치 <a class="header-anchor" href="#주기억장치" aria-label="Permalink to &quot;주기억장치&quot;">​</a></h4><table tabindex="0"><thead><tr><th>종류</th><th>특성</th><th>주요 용도</th></tr></thead><tbody><tr><td>DRAM</td><td>집적도가 높고 비교적 느림, 주기적인 재충전 필요</td><td>주 메모리</td></tr><tr><td>SRAM</td><td>빠르고 비싸며 집적도가 낮음, 재충전 불필요</td><td>CPU 캐시</td></tr><tr><td>ROM</td><td>전원이 꺼져도 내용 유지</td><td>펌웨어 저장</td></tr></tbody></table><p>ROM 계열은 기록 방식에 따라 Mask ROM, PROM, EPROM, EEPROM·Flash 등으로 나뉜다. 현대 PC의 UEFI 펌웨어는 일반적으로 플래시 메모리에 저장된다.</p><h4 id="입력장치-구분" tabindex="-1">입력장치 구분 <a class="header-anchor" href="#입력장치-구분" aria-label="Permalink to &quot;입력장치 구분&quot;">​</a></h4><ul><li>OMR(Optical Mark Reader): 답안지처럼 표시된 마크 판독</li><li>OCR(Optical Character Recognition): 인쇄·필기 문자를 문자 데이터로 변환</li><li>MICR(Magnetic Ink Character Recognition): 자기 잉크로 인쇄된 문자 판독</li></ul><h3 id="linux-설치-전-하드웨어-확인" tabindex="-1">Linux 설치 전 하드웨어 확인 <a class="header-anchor" href="#linux-설치-전-하드웨어-확인" aria-label="Permalink to &quot;Linux 설치 전 하드웨어 확인&quot;">​</a></h3><h4 id="cpu-1" tabindex="-1">CPU <a class="header-anchor" href="#cpu-1" aria-label="Permalink to &quot;CPU&quot;">​</a></h4><ul><li>배포판이 CPU 아키텍처를 지원하는지 확인한다.</li><li>대표 아키텍처: x86-64, ARM64, RISC-V, PowerPC 등</li><li>가상 머신을 사용할 경우 Intel VT-x 또는 AMD-V 같은 하드웨어 가상화 기능도 확인한다.</li><li>병렬성(Parallelism)은 여러 코어·프로세서에서 실제 계산을 동시에 수행하는 것이고, 동시성(Concurrency)은 여러 작업의 진행이 시간상 겹치는 개념이다.</li></ul><h4 id="메인보드와-펌웨어" tabindex="-1">메인보드와 펌웨어 <a class="header-anchor" href="#메인보드와-펌웨어" aria-label="Permalink to &quot;메인보드와 펌웨어&quot;">​</a></h4><ul><li>칩셋, 저장장치 컨트롤러와 네트워크 장치 지원 여부 확인</li><li>설치·부팅 문제가 있으면 UEFI 설정과 펌웨어 업데이트 확인</li><li>Secure Boot, 저장장치 모드와 부팅 순서 확인</li></ul><h4 id="메모리" tabindex="-1">메모리 <a class="header-anchor" href="#메모리" aria-label="Permalink to &quot;메모리&quot;">​</a></h4><ul><li>배포판과 실행할 서비스의 최소·권장 용량 확인</li><li>64비트 환경에서는 32비트보다 넓은 주소 공간을 사용할 수 있다.</li><li>지원 가능한 최대 메모리는 CPU뿐 아니라 메인보드와 배포판·커널 설정에도 좌우된다.</li><li>swap은 메모리 부족을 보완하지만 RAM을 대체할 만큼 빠르지는 않다.</li></ul><h4 id="저장장치" tabindex="-1">저장장치 <a class="header-anchor" href="#저장장치" aria-label="Permalink to &quot;저장장치&quot;">​</a></h4><p>Linux에서는 저장장치도 장치 파일로 표현한다.</p><table tabindex="0"><thead><tr><th>장치</th><th>일반적인 이름 예</th></tr></thead><tbody><tr><td>SATA·SAS·SCSI·USB 저장장치</td><td><code>/dev/sda</code>, <code>/dev/sdb</code></td></tr><tr><td>NVMe SSD</td><td><code>/dev/nvme0n1</code></td></tr><tr><td>오래된 IDE 장치</td><td><code>/dev/hda</code></td></tr></tbody></table><p>장치명은 검색 순서에 따라 바뀔 수 있으므로 영구 설정에는 UUID나 <code>/dev/disk/by-*</code> 링크를 사용하는 편이 안전하다.</p><h4 id="그래픽·네트워크·입력장치" tabindex="-1">그래픽·네트워크·입력장치 <a class="header-anchor" href="#그래픽·네트워크·입력장치" aria-label="Permalink to &quot;그래픽·네트워크·입력장치&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lspci</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # PCI 장치 확인</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lspci</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Ei</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vga|3d|display&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lspci</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ethernet</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsusb</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # USB 장치 확인</span></span></code></pre></div><ul><li>일반적인 장치는 커널 내장 드라이버로 동작한다.</li><li>최신 GPU, Wi-Fi와 특수 장치는 별도 펌웨어나 제조사 드라이버가 필요할 수 있다.</li><li>네트워크 설치 전 IP 주소, 프리픽스·넷마스크, 게이트웨이와 DNS 정보를 확인한다.</li></ul><h2 id="raid" tabindex="-1">RAID <a class="header-anchor" href="#raid" aria-label="Permalink to &quot;RAID&quot;">​</a></h2><p>RAID(Redundant Array of Independent Disks)는 여러 디스크를 하나의 논리 장치로 묶어 성능, 용량 또는 장애 허용성을 높이는 기술이다.</p><ul><li>Striping: 데이터를 여러 디스크에 나누어 기록</li><li>Mirroring: 같은 데이터를 여러 디스크에 복제</li><li>Parity: 손실된 데이터를 계산해 복구하기 위한 정보</li></ul><p>RAID는 백업이 아니다. 실수로 삭제하거나 손상된 데이터도 함께 반영될 수 있으므로 별도 백업이 필요하다.</p><h3 id="raid-레벨-비교" tabindex="-1">RAID 레벨 비교 <a class="header-anchor" href="#raid-레벨-비교" aria-label="Permalink to &quot;RAID 레벨 비교&quot;">​</a></h3><p><code>N</code>은 같은 크기의 디스크 수, <code>S</code>는 가장 작은 디스크의 용량이다.</p><table tabindex="0"><thead><tr><th>레벨</th><th>구성</th><th style="text-align:right;">최소 디스크</th><th style="text-align:right;">사용 가능 용량</th><th style="text-align:right;">장애 허용</th><th>핵심</th></tr></thead><tbody><tr><td>RAID 0</td><td>Striping</td><td style="text-align:right;">2</td><td style="text-align:right;"><code>N × S</code></td><td style="text-align:right;">0개</td><td>빠르지만 디스크 하나만 고장 나도 전체 손실</td></tr><tr><td>RAID 1</td><td>Mirroring</td><td style="text-align:right;">2</td><td style="text-align:right;">보통 <code>S</code></td><td style="text-align:right;">미러당 1개</td><td>안정적이지만 2개 구성의 공간 효율 50%</td></tr><tr><td>RAID 2</td><td>비트 Striping + Hamming ECC</td><td style="text-align:right;">다수</td><td style="text-align:right;">구성에 따라 다름</td><td style="text-align:right;">구성에 따라 다름</td><td>현재 거의 사용하지 않음</td></tr><tr><td>RAID 3</td><td>바이트 Striping + 전용 Parity</td><td style="text-align:right;">3</td><td style="text-align:right;"><code>(N-1) × S</code></td><td style="text-align:right;">1개</td><td>전용 패리티 디스크 사용, 거의 사용하지 않음</td></tr><tr><td>RAID 4</td><td>블록 Striping + 전용 Parity</td><td style="text-align:right;">3</td><td style="text-align:right;"><code>(N-1) × S</code></td><td style="text-align:right;">1개</td><td>패리티 디스크의 쓰기 병목</td></tr><tr><td>RAID 5</td><td>블록 Striping + 분산 Parity</td><td style="text-align:right;">3</td><td style="text-align:right;"><code>(N-1) × S</code></td><td style="text-align:right;">1개</td><td>성능·용량·안정성의 균형</td></tr><tr><td>RAID 6</td><td>블록 Striping + 이중 분산 Parity</td><td style="text-align:right;">4</td><td style="text-align:right;"><code>(N-2) × S</code></td><td style="text-align:right;">2개</td><td>RAID 5보다 안전하지만 쓰기 비용 증가</td></tr><tr><td>RAID 0+1</td><td>Stripe 묶음을 Mirror</td><td style="text-align:right;">4</td><td style="text-align:right;"><code>N/2 × S</code></td><td style="text-align:right;">구성에 따라 다름</td><td>한 Stripe 묶음 장애 후 허용성 감소</td></tr><tr><td>RAID 1+0</td><td>Mirror 묶음을 Stripe</td><td style="text-align:right;">4</td><td style="text-align:right;"><code>N/2 × S</code></td><td style="text-align:right;">미러별 1개 가능</td><td>RAID 0+1보다 일반적으로 복구와 장애 허용성이 좋음</td></tr></tbody></table><p>RAID 10은 RAID 1+0을 뜻한다. 교재에 나오는 RAID 5+3 같은 표기는 표준 RAID 레벨이라기보다 여러 RAID 구성을 중첩한 특수 구성으로 이해한다.</p><h3 id="raid-선택-기준" tabindex="-1">RAID 선택 기준 <a class="header-anchor" href="#raid-선택-기준" aria-label="Permalink to &quot;RAID 선택 기준&quot;">​</a></h3><ul><li>최대 성능, 데이터 보호 불필요: RAID 0</li><li>단순한 이중화: RAID 1</li><li>용량 효율과 1개 디스크 장애 허용: RAID 5</li><li>대용량 배열에서 2개 디스크 장애 허용: RAID 6</li><li>높은 성능과 안정성: RAID 10</li></ul><p>패리티는 장애 복구 정보이며 백업 복사본은 아니다. RAID 5·6은 고장 난 디스크를 교체한 뒤 재구축하는 동안 성능이 낮아지고 추가 장애 위험이 커질 수 있다.</p><h2 id="디스크-인터페이스" tabindex="-1">디스크 인터페이스 <a class="header-anchor" href="#디스크-인터페이스" aria-label="Permalink to &quot;디스크 인터페이스&quot;">​</a></h2><table tabindex="0"><thead><tr><th>인터페이스</th><th>전송 방식</th><th>주요 환경</th><th>특징</th></tr></thead><tbody><tr><td>IDE·PATA</td><td>병렬</td><td>구형 PC</td><td>40핀 리본 케이블, 현재 거의 사용하지 않음</td></tr><tr><td>SATA</td><td>직렬</td><td>PC, 일반 서버</td><td>보급형 저장장치의 대표 규격</td></tr><tr><td>Parallel SCSI</td><td>병렬</td><td>구형 서버·워크스테이션</td><td>안정성과 장치 확장성, 현재는 감소</td></tr><tr><td>SAS</td><td>직렬</td><td>서버·데이터센터</td><td>SCSI 명령 체계, 고성능·신뢰성·확장성</td></tr></tbody></table><h3 id="sata-세대별-링크-속도" tabindex="-1">SATA 세대별 링크 속도 <a class="header-anchor" href="#sata-세대별-링크-속도" aria-label="Permalink to &quot;SATA 세대별 링크 속도&quot;">​</a></h3><table tabindex="0"><thead><tr><th>세대</th><th style="text-align:right;">이론상 링크 속도</th><th>흔히 부르는 이름</th></tr></thead><tbody><tr><td>SATA 1</td><td style="text-align:right;">1.5 Gbit/s</td><td>SATA 150</td></tr><tr><td>SATA 2</td><td style="text-align:right;">3 Gbit/s</td><td>SATA 300</td></tr><tr><td>SATA 3</td><td style="text-align:right;">6 Gbit/s</td><td>SATA 600</td></tr></tbody></table><p>링크 속도는 인코딩 오버헤드를 포함하므로 실제 데이터 전송률은 표기값보다 낮다.</p><h3 id="sata와-sas" tabindex="-1">SATA와 SAS <a class="header-anchor" href="#sata와-sas" aria-label="Permalink to &quot;SATA와 SAS&quot;">​</a></h3><ul><li>SATA: 가격과 범용성을 중시하는 PC·일반 서버용</li><li>SAS: 이중 포트, 확장성, 신뢰성과 연속 운용을 중시하는 기업용</li><li>SAS 컨트롤러는 보통 SATA 드라이브도 연결할 수 있지만, SATA 컨트롤러에는 SAS 드라이브를 연결할 수 없다.</li></ul><p>NVMe는 PCI Express 위에서 동작하며 SATA·SAS와 다른 현대적인 SSD 인터페이스다.</p><h2 id="시험-핵심" tabindex="-1">시험 핵심 <a class="header-anchor" href="#시험-핵심" aria-label="Permalink to &quot;시험 핵심&quot;">​</a></h2><ul><li>CPU 구성: 레지스터, ALU, 제어장치</li><li>DRAM은 주 메모리, SRAM은 캐시, ROM·Flash는 비휘발성 펌웨어 저장</li><li>OMR은 마크, OCR은 문자, MICR은 자기 잉크 문자 판독</li><li>SATA·SCSI 계열은 보통 <code>/dev/sdX</code>, NVMe는 <code>/dev/nvme0n1</code></li><li>RAID 0은 성능만, RAID 1은 Mirroring, RAID 5는 분산 Parity 1개, RAID 6은 Parity 2개</li><li>RAID 10은 Mirror 후 Stripe이며 RAID 0+1보다 일반적으로 장애 대응에 유리</li><li>PATA·SCSI는 병렬, SATA·SAS는 직렬</li></ul><h2 id="리눅스의-구조" tabindex="-1">리눅스의 구조 <a class="header-anchor" href="#리눅스의-구조" aria-label="Permalink to &quot;리눅스의 구조&quot;">​</a></h2><h3 id="부트-매니저" tabindex="-1">부트 매니저 <a class="header-anchor" href="#부트-매니저" aria-label="Permalink to &quot;부트 매니저&quot;">​</a></h3><p>부트 매니저(Boot Manager)는 디스크에 저장된 운영체제의 커널을 메모리에 적재하는 프로그램으로, 부트로더(Boot Loader)라고도 한다.</p><h4 id="부팅-흐름" tabindex="-1">부팅 흐름 <a class="header-anchor" href="#부팅-흐름" aria-label="Permalink to &quot;부팅 흐름&quot;">​</a></h4><ul><li>BIOS/MBR 환경: <code>POST → MBR의 부트 코드 → GRUB → 커널·initramfs → systemd(PID 1)</code> 순으로 진행된다.</li><li>전통적인 MBR은 디스크의 첫 섹터에 위치하며 크기가 512바이트로 제한된다. 따라서 작은 1단계 코드가 파일 시스템을 해석할 수 있는 다음 단계 부트로더를 호출한다.</li><li>UEFI/GPT 환경에서는 펌웨어가 EFI 시스템 파티션(ESP)의 실행 파일을 직접 불러오므로 MBR 방식의 제약을 받지 않는다.</li></ul><table tabindex="0"><thead><tr><th>종류</th><th>특징</th><th>주요 설정 파일</th></tr></thead><tbody><tr><td>LILO</td><td>오래된 리눅스 부트로더. 설정 변경 후 <code>lilo</code>를 실행해 MBR에 다시 기록해야 함</td><td><code>/etc/lilo.conf</code></td></tr><tr><td>GRUB Legacy</td><td>대화형 메뉴와 명령행, 네트워크 부팅 지원</td><td><code>/boot/grub/grub.conf</code> 또는 <code>menu.lst</code></td></tr><tr><td>GRUB2</td><td>현재 널리 사용하며 BIOS·UEFI, GPT, RAID, LVM과 여러 파일 시스템을 지원</td><td>아래 참고</td></tr></tbody></table><h4 id="grub2-사용과-설정" tabindex="-1">GRUB2 사용과 설정 <a class="header-anchor" href="#grub2-사용과-설정" aria-label="Permalink to &quot;GRUB2 사용과 설정&quot;">​</a></h4><ul><li>메뉴에서 방향키와 <code>Enter</code>로 부팅 항목을 선택한다.</li><li><code>e</code>는 선택 항목의 커널 인자를 임시 편집하고, <code>c</code>는 GRUB 명령행으로 진입한다. 편집 후 <code>Ctrl</code>+<code>x</code> 또는 <code>F10</code>으로 부팅한다.</li><li>메뉴에서 바꾼 값은 해당 부팅에만 적용되며 설정 파일에는 저장되지 않는다.</li><li>원본 설정은 <code>/etc/default/grub</code>와 <code>/etc/grub.d/</code>에 있다. 이를 바탕으로 생성되는 <code>/boot/grub2/grub.cfg</code>(레드햇 계열) 또는 <code>/boot/grub/grub.cfg</code>(데비안 계열)는 직접 수정하지 않는다.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 레드햇 계열</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grub2-mkconfig</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /boot/grub2/grub.cfg</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 데비안·우분투 계열</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">update-grub</span></span></code></pre></div><table tabindex="0"><thead><tr><th><code>/etc/default/grub</code> 항목</th><th>의미</th></tr></thead><tbody><tr><td><code>GRUB_TIMEOUT</code></td><td>메뉴에서 사용자 입력을 기다리는 시간</td></tr><tr><td><code>GRUB_DEFAULT</code></td><td>기본 부팅 항목의 번호·이름 또는 <code>saved</code></td></tr><tr><td><code>GRUB_CMDLINE_LINUX</code></td><td>모든 리눅스 항목에 전달할 커널 매개변수</td></tr><tr><td><code>GRUB_DISABLE_SUBMENU</code></td><td>하위 메뉴 사용 여부</td></tr><tr><td><code>GRUB_DISABLE_RECOVERY</code></td><td><code>true</code>이면 복구 메뉴 항목을 생성하지 않음</td></tr></tbody></table><p>저장형 기본 항목은 <code>grub2-set-default</code>로 지정하고 <code>grub2-editenv list</code>로 확인한다. GRUB2 메뉴 편집을 보호하려면 <code>grub2-mkpasswd-pbkdf2</code>로 해시를 만든 뒤 <code>/etc/grub.d/40_custom</code>에 <code>set superusers</code>와 <code>password_pbkdf2</code>를 설정하고 <code>grub.cfg</code>를 다시 생성한다. 이는 부트 메뉴를 보호하는 기능이며 디스크 자체를 암호화하지는 않는다.</p><h3 id="주요-디렉터리-구조" tabindex="-1">주요 디렉터리 구조 <a class="header-anchor" href="#주요-디렉터리-구조" aria-label="Permalink to &quot;주요 디렉터리 구조&quot;">​</a></h3><p>FHS(File System Hierarchy Standard)는 배포판 사이에서 디렉터리의 용도를 일관되게 유지하기 위한 표준이다.</p><table tabindex="0"><thead><tr><th>경로</th><th>용도</th></tr></thead><tbody><tr><td><code>/</code></td><td>모든 파일과 디렉터리의 출발점인 루트 디렉터리</td></tr><tr><td><code>/boot</code></td><td>커널, initramfs, 부트로더 관련 파일</td></tr><tr><td><code>/dev</code></td><td>디스크·터미널 등 장치를 나타내는 장치 파일</td></tr><tr><td><code>/etc</code></td><td>시스템 전역 설정 파일과 초기화 설정</td></tr><tr><td><code>/home</code></td><td>일반 사용자의 홈 디렉터리</td></tr><tr><td><code>/root</code></td><td><code>root</code> 사용자의 홈 디렉터리</td></tr><tr><td><code>/run</code></td><td>부팅 후 생성되는 PID·소켓 등 휘발성 런타임 데이터</td></tr><tr><td><code>/tmp</code></td><td>프로그램이 만드는 임시 파일. 일반적으로 모든 사용자가 쓰며 Sticky Bit 적용</td></tr><tr><td><code>/usr</code></td><td>사용자 명령, 라이브러리, 헤더와 공유 데이터</td></tr><tr><td><code>/var</code></td><td>로그·스풀·캐시처럼 실행 중 크기가 변하는 데이터</td></tr><tr><td><code>/proc</code></td><td>프로세스와 커널 상태를 보여 주는 가상 파일 시스템</td></tr><tr><td><code>/sys</code></td><td>장치와 커널 객체를 보여 주는 <code>sysfs</code> 가상 파일 시스템</td></tr><tr><td><code>/media</code></td><td>이동식 매체의 자동 마운트 지점</td></tr><tr><td><code>/mnt</code></td><td>관리자가 임시로 파일 시스템을 마운트하는 지점</td></tr><tr><td><code>/opt</code></td><td>별도로 설치하는 응용 프로그램 패키지</td></tr></tbody></table><p>전통적으로 <code>/bin</code>에는 필수 사용자 명령, <code>/sbin</code>에는 관리 명령, <code>/lib</code>에는 필수 라이브러리가 위치했다. 현대 배포판은 이 경로들을 각각 <code>/usr/bin</code>, <code>/usr/sbin</code>, <code>/usr/lib</code>로 연결하는 <strong>usr merge</strong> 구성을 흔히 사용한다. 주요 하위 경로는 다음과 같다.</p><ul><li><code>/var/log</code>: 로그, <code>/var/spool</code>: 처리 대기 데이터, <code>/var/tmp</code>: 재부팅 후에도 유지할 수 있는 임시 파일</li><li><code>/usr/include</code>: C/C++ 헤더, <code>/usr/src</code>: 커널 등 소스 코드</li><li><code>/lib/modules</code>: 설치된 커널의 모듈</li></ul><h3 id="부팅과-셧다운" tabindex="-1">부팅과 셧다운 <a class="header-anchor" href="#부팅과-셧다운" aria-label="Permalink to &quot;부팅과 셧다운&quot;">​</a></h3><p>부팅은 전원을 켠 뒤 운영체제를 사용할 수 있는 상태로 만드는 과정이다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>펌웨어·POST → 부트로더 → 커널·initramfs → init 또는 systemd → 서비스 → 로그인 프롬프트</span></span></code></pre></div><p>전통적인 SysV init은 실행 레벨에 따라 초기화 스크립트를 실행한다. 현대의 systemd에서는 이에 대응하는 target을 사용한다.</p><table tabindex="0"><thead><tr><th>실행 레벨</th><th>SysV 의미</th><th>systemd 대응 target</th></tr></thead><tbody><tr><td>0</td><td>시스템 종료</td><td><code>poweroff.target</code></td></tr><tr><td>1</td><td>단일 사용자·복구 모드</td><td><code>rescue.target</code></td></tr><tr><td>2</td><td>배포판별 다중 사용자 모드</td><td><code>multi-user.target</code></td></tr><tr><td>3</td><td>네트워크를 지원하는 텍스트 다중 사용자 모드</td><td><code>multi-user.target</code></td></tr><tr><td>4</td><td>미사용 또는 사용자 정의</td><td><code>multi-user.target</code></td></tr><tr><td>5</td><td>그래픽 다중 사용자 모드</td><td><code>graphical.target</code></td></tr><tr><td>6</td><td>재부팅</td><td><code>reboot.target</code></td></tr></tbody></table><h4 id="로그인과-로그아웃" tabindex="-1">로그인과 로그아웃 <a class="header-anchor" href="#로그인과-로그아웃" aria-label="Permalink to &quot;로그인과 로그아웃&quot;">​</a></h4><table tabindex="0"><thead><tr><th>파일</th><th>표시 시점</th></tr></thead><tbody><tr><td><code>/etc/issue</code></td><td>로컬 로그인 전</td></tr><tr><td><code>/etc/issue.net</code></td><td>원격 로그인 전. 실제 사용 여부는 해당 서비스 설정에 따름</td></tr><tr><td><code>/etc/motd</code></td><td>인증에 성공한 뒤</td></tr></tbody></table><ul><li>터미널에서는 <code>exit</code>, <code>logout</code> 또는 <code>Ctrl</code>+<code>d</code>로 세션을 끝낸다.</li><li>셸의 <code>TMOUT</code> 값을 초 단위로 설정하면 입력이 없는 세션을 자동 종료할 수 있다.</li></ul><h4 id="종료와-재시작" tabindex="-1">종료와 재시작 <a class="header-anchor" href="#종료와-재시작" aria-label="Permalink to &quot;종료와 재시작&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> poweroff</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 전원 끄기</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 재부팅</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shutdown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> now</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # 즉시 종료</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shutdown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 5분 뒤 재부팅</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shutdown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # 예약 취소</span></span></code></pre></div><p><code>halt</code>, <code>poweroff</code>, <code>reboot</code>, <code>init 0</code>, <code>init 6</code>도 시험에서 다루는 전통적인 명령이다. 파일 시스템 손상을 막기 위해 전원을 직접 차단하지 말고 정상 종료 절차를 사용한다.</p><h3 id="systemd" tabindex="-1">systemd <a class="header-anchor" href="#systemd" aria-label="Permalink to &quot;systemd&quot;">​</a></h3><p>systemd는 SysV init을 대체하는 시스템·서비스 관리자이며 일반적으로 PID 1로 실행된다. 의존성이 없는 유닛은 병렬로 시작하고, 소켓·장치·경로 요청에 따라 서비스를 필요할 때 실행할 수 있다.</p><h4 id="유닛-유형" tabindex="-1">유닛 유형 <a class="header-anchor" href="#유닛-유형" aria-label="Permalink to &quot;유닛 유형&quot;">​</a></h4><table tabindex="0"><thead><tr><th>유형</th><th>확장자</th><th>용도</th></tr></thead><tbody><tr><td>Service</td><td><code>.service</code></td><td>서비스와 데몬</td></tr><tr><td>Target</td><td><code>.target</code></td><td>여러 유닛을 묶는 동기화 지점. 실행 레벨과 유사</td></tr><tr><td>Socket</td><td><code>.socket</code></td><td>소켓 기반 활성화</td></tr><tr><td>Timer</td><td><code>.timer</code></td><td>시간 기반 활성화</td></tr><tr><td>Mount·Automount</td><td><code>.mount</code>, <code>.automount</code></td><td>파일 시스템 마운트와 자동 마운트</td></tr><tr><td>Path</td><td><code>.path</code></td><td>파일·디렉터리 변경 감시</td></tr><tr><td>Device</td><td><code>.device</code></td><td>커널이 인식한 장치</td></tr><tr><td>Swap</td><td><code>.swap</code></td><td>스왑 장치·파일</td></tr></tbody></table><p>동일한 이름의 유닛이 여러 곳에 있으면 관리자 설정이 공급자 설정을 덮어쓴다.</p><ol><li><code>/etc/systemd/system/</code>: 관리자가 작성·수정한 영구 설정</li><li><code>/run/systemd/system/</code>: 실행 중 임시로 생성된 설정</li><li><code>/usr/lib/systemd/system/</code>: 패키지가 설치한 공급자 설정(일부 배포판은 <code>/lib/systemd/system/</code>)</li></ol><p>유닛 파일은 보통 다음 섹션으로 구성된다.</p><ul><li><code>[Unit]</code>: <code>Description</code>, <code>After</code>, <code>Requires</code>, <code>Wants</code> 등 공통 정보와 관계. <code>After</code>는 시작 순서만 정한다.</li><li><code>[Service]</code> 등 유형별 섹션: <code>ExecStart</code>, <code>ExecStop</code>처럼 해당 유닛의 동작을 정의한다.</li><li><code>[Install]</code>: <code>WantedBy</code>, <code>RequiredBy</code> 등 <code>enable</code>할 때 사용할 정보를 정의한다.</li></ul><h4 id="주요-명령" tabindex="-1">주요 명령 <a class="header-anchor" href="#주요-명령" aria-label="Permalink to &quot;주요 명령&quot;">​</a></h4><table tabindex="0"><thead><tr><th>작업</th><th>명령</th></tr></thead><tbody><tr><td>시작·중지·재시작</td><td>\`systemctl start</td></tr><tr><td>실행 중일 때만 재시작</td><td><code>systemctl try-restart name.service</code></td></tr><tr><td>설정 다시 읽기</td><td><code>systemctl reload name.service</code></td></tr><tr><td>상태 확인</td><td><code>systemctl status name.service</code></td></tr><tr><td>부팅 시 자동 시작·해제</td><td>\`systemctl enable</td></tr><tr><td>즉시 시작하면서 자동 시작</td><td><code>systemctl enable --now name.service</code></td></tr><tr><td>기본 target 확인·변경</td><td><code>systemctl get-default</code>, <code>systemctl set-default name.target</code></td></tr><tr><td>현재 target 전환</td><td><code>systemctl isolate name.target</code></td></tr><tr><td>복구·응급 모드</td><td><code>systemctl rescue</code>, <code>systemctl emergency</code></td></tr></tbody></table><p><code>enable</code>은 부팅 시 실행될 링크를 만드는 작업으로 현재 서비스를 시작하는 것과 다르다. 변경된 유닛 파일을 다시 읽힐 때는 <code>systemctl daemon-reload</code>를 사용한다. SSH로 접근 가능한 원격 호스트는 <code>systemctl -H user@host status name.service</code>처럼 제어할 수도 있다.</p><h3 id="파일-시스템의-이해" tabindex="-1">파일 시스템의 이해 <a class="header-anchor" href="#파일-시스템의-이해" aria-label="Permalink to &quot;파일 시스템의 이해&quot;">​</a></h3><p>파일 시스템은 디스크의 블록을 파일과 디렉터리로 조직하고, 캐시·메타데이터·오류 복구 기능을 제공하는 계층이다.</p><h4 id="ext-계열의-기본-구조" tabindex="-1">ext 계열의 기본 구조 <a class="header-anchor" href="#ext-계열의-기본-구조" aria-label="Permalink to &quot;ext 계열의 기본 구조&quot;">​</a></h4><p>ext2의 디스크는 부트 영역 뒤에 여러 블록 그룹이 이어지는 형태다. 각 블록 그룹은 다음 정보를 가진다.</p><table tabindex="0"><thead><tr><th>구성 요소</th><th>역할</th></tr></thead><tbody><tr><td>슈퍼 블록</td><td>블록 크기, 전체 블록·inode 수 등 파일 시스템 전체 정보</td></tr><tr><td>그룹 디스크립터</td><td>각 블록 그룹의 비트맵·inode 테이블 위치와 여유 공간 정보</td></tr><tr><td>블록 비트맵</td><td>데이터 블록의 사용 여부</td></tr><tr><td>inode 비트맵</td><td>inode의 사용 여부</td></tr><tr><td>inode 테이블</td><td>파일별 inode 집합</td></tr><tr><td>데이터 블록</td><td>디렉터리 항목과 실제 파일 내용</td></tr></tbody></table><p>inode에는 파일 형식·권한, UID/GID, 크기, 링크 수, 타임스탬프와 데이터 블록 위치가 기록된다. <strong>파일 이름은 inode가 아니라 디렉터리 항목에 저장</strong>되며, 디렉터리는 이름을 inode 번호에 대응시킨다. ext 계열에서 루트 디렉터리는 inode 2를 사용한다.</p><p>고전적인 ext2 inode는 15개 블록 포인터를 가지며 12개는 직접 블록, 나머지는 단일·이중·삼중 간접 블록을 가리킨다. ext4는 큰 파일을 효율적으로 나타내기 위해 연속 블록 범위를 기록하는 extent를 주로 사용한다.</p><h4 id="로컬-파일-시스템" tabindex="-1">로컬 파일 시스템 <a class="header-anchor" href="#로컬-파일-시스템" aria-label="Permalink to &quot;로컬 파일 시스템&quot;">​</a></h4><table tabindex="0"><thead><tr><th>파일 시스템</th><th>핵심 특징</th></tr></thead><tbody><tr><td>ext2</td><td>저널링이 없는 ext 계열. 비정상 종료 후 <code>fsck</code> 시간이 길 수 있음</td></tr><tr><td>ext3</td><td>ext2 호환 구조에 저널링을 추가</td></tr><tr><td>ext4</td><td>extent, 지연 할당, 멀티블록 할당, 저널 체크섬을 지원하는 대표 범용 파일 시스템</td></tr><tr><td>XFS</td><td>고성능 64비트 저널링 파일 시스템. 대용량·병렬 I/O와 온라인 확장에 강함</td></tr><tr><td>Btrfs</td><td>Copy-on-Write, 스냅샷·서브볼륨, 체크섬, 압축과 다중 장치 기능 제공</td></tr><tr><td>ZFS</td><td>파일 시스템과 볼륨 관리를 결합하고 CoW, 체크섬, 스냅샷, 자동 복구 기능 제공</td></tr><tr><td>ReiserFS·JFS</td><td>각각 Reiser 계열과 IBM이 개발한 저널링 파일 시스템으로 현재는 주로 기존 시스템에서 접함</td></tr></tbody></table><p>파일·파일 시스템의 최대 크기는 파일 시스템 버전, 블록 크기와 구현에 따라 달라지므로 오래된 교재의 단일 수치보다 구조와 특징을 우선해 기억한다.</p><h4 id="그-밖의-파일-시스템" tabindex="-1">그 밖의 파일 시스템 <a class="header-anchor" href="#그-밖의-파일-시스템" aria-label="Permalink to &quot;그 밖의 파일 시스템&quot;">​</a></h4><table tabindex="0"><thead><tr><th>종류</th><th>용도</th></tr></thead><tbody><tr><td>Raw partition</td><td>파일 시스템 없이 블록 장치를 직접 사용. 관리가 어렵지만 오버헤드가 적음</td></tr><tr><td>OCFS2</td><td>여러 노드가 공유 저장소에 접근하는 범용 클러스터 파일 시스템</td></tr><tr><td>VFAT</td><td>FAT 계열과 호환되는 이동식 매체용 파일 시스템</td></tr><tr><td>ISO 9660</td><td>CD-ROM 표준 파일 시스템</td></tr><tr><td>NFS</td><td>유닉스·리눅스의 네트워크 파일 공유</td></tr><tr><td>SMB/CIFS</td><td>윈도우 계열과의 네트워크 파일 공유</td></tr><tr><td>procfs·sysfs</td><td>디스크에 저장되지 않고 프로세스·커널·장치 정보를 제공하는 가상 파일 시스템</td></tr></tbody></table><h4 id="시험-핵심-1" tabindex="-1">시험 핵심 <a class="header-anchor" href="#시험-핵심-1" aria-label="Permalink to &quot;시험 핵심&quot;">​</a></h4><ul><li>GRUB2 메뉴의 <code>e</code>는 임시 편집, <code>c</code>는 명령행이며 영구 설정은 원본 파일 수정 후 <code>grub2-mkconfig</code>로 생성한다.</li><li><code>/proc</code>, <code>/sys</code>는 가상 파일 시스템이고 <code>/run</code>은 부팅 후의 휘발성 런타임 데이터다.</li><li>SysV 실행 레벨 3은 텍스트 다중 사용자, 5는 그래픽, 0은 종료, 6은 재부팅이다.</li><li><code>systemctl enable</code>은 자동 시작 설정, <code>start</code>는 현재 시작이며 <code>enable --now</code>는 둘을 함께 수행한다.</li><li>디렉터리는 파일 이름과 inode 번호의 대응을 저장하고 inode는 권한·소유자·블록 위치 등 메타데이터를 저장한다.</li><li>ext3의 핵심은 저널링, ext4의 핵심은 extent와 지연·멀티블록 할당이다.</li></ul>`,98)])])}const u=d(r,[["render",o]]);export{b as __pageData,u as default};
